pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address manager) public {
        vm.assume(manager != address(0));
        // Deploy a minimal LRTConfig mock that grants MANAGER role to the fuzzed manager
        MockLRTConfig config = new MockLRTConfig();
        config.grantManager(manager);
        // Initialize C with the config so it accepts pause from manager
        c.initialize(address(config));

        // Pause the contract as the manager
        vm.prank(manager);
        c.pause();

        // The reference C returns true after pause, buggy one always returns false
        assertTrue(c.paused());
    }
}

// Minimal mock to satisfy LRTConfigRoleChecker and initialization without complex setup
contract MockLRTConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 public constant MANAGER = keccak256("MANAGER");

    constructor() {
        roles[DEFAULT_ADMIN_ROLE][msg.sender] = true;
    }

    function grantManager(address account) external {
        roles[MANAGER][account] = true;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }

    function isSupportedAsset(address) external pure returns (bool) {
        return false;
    }

    function depositLimitByAsset(address) external pure returns (uint256) {
        return 0;
    }

    function rsETH() external pure returns (address) {
        return address(0);
    }

    function getContract(bytes32) external pure returns (address) {
        return address(0);
    }
}

