pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address admin, address manager) public {
        vm.assume(admin != address(0));
        vm.assume(manager != address(0));
        vm.assume(admin != manager);
        vm.assume(!vm.isContract(admin));
        vm.assume(!vm.isContract(manager));

        // Deploy a minimal LRTConfig mock to pass role checks
        address config = address(new LRTConfigMock(admin, manager));
        vm.prank(admin);
        c.initialize(config);

        // Manager pauses the contract
        vm.prank(manager);
        c.pause();

        // The property: after pausing, paused() must return true
        bool isPaused = c.paused();
        assertTrue(isPaused);
    }
}

contract LRTConfigMock {
    address admin;
    address manager;
    constructor(address _admin, address _manager) {
        admin = _admin;
        manager = _manager;
    }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        if (role == 0x00 && account == admin) return true;
        if (role == keccak256("MANAGER") && account == manager) return true;
        return false;
    }
    function isSupportedAsset(address) external pure returns (bool) {
        return true;
    }
    function depositLimitByAsset(address) external pure returns (uint256) {
        return type(uint256).max;
    }
    function getContract(bytes32) external view returns (address) {
        return address(0);
    }
    function rsETH() external view returns (address) {
        return address(0);
    }
    function assetStrategy(address) external view returns (address) {
        return address(0);
    }
    function getSupportedAssetList() external view returns (address[] memory) {
        return new address[](0);
    }
    function getLSTToken(bytes32) external view returns (address) {
        return address(0);
    }
}

